 'use strict';
(()=>{
const root=document.getElementById('app'),C=window.BARBER_CONFIG;
let visual=null,masterVisualShop=null,isMaster=false,session=null,shop=null,shopBlocked=false,lastShopCheck=0,services=[],staff=[],clients=[],appointments=[],current='home',selectedSlot='',capabilities=[],professional=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const isoDay=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
const slug=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,55);
const validColor=v=>/^#[0-9a-fA-F]{6}$/.test(v||'')?v:'#d4af37';
const safeMedia=v=>typeof v==='string'&&v.startsWith(C.supabaseUrl+'/storage/v1/object/public/ba2-identidade/')?v:'';
const setVisual=v=>{visual=v||null;let st=document.getElementById('ba2-visual');if(!st){st=document.createElement('style');st.id='ba2-visual';document.head.appendChild(st)}const c=validColor(visual?.cor);const bg=safeMedia(visual?.fundo_url);st.textContent=`#app .gold{color:${c}!important}#app .btn:not(.danger):not(.secondary){background:${c}!important;border-color:${c}!important;color:#171717!important}#app header{border-bottom:2px solid ${c}!important}#app .wrap{${bg?`background-image:linear-gradient(rgba(15,16,20,.83),rgba(15,16,20,.88)),url("${bg}");background-position:center;background-size:cover;background-attachment:fixed;`:''}}`;};
const visualHeader=()=>visual?.logo_url&&safeMedia(visual.logo_url)?`<img src="${esc(visual.logo_url)}" alt="Logo" style="width:48px;height:48px;object-fit:contain;border-radius:8px;vertical-align:middle;margin-right:10px">`:'';
const shell=(body,nav='')=>{root.innerHTML=`<header><div class="brand">${visualHeader()}✂ <span class="gold">Barber</span>Agenda <span class="small">V2</span></div><span class="pill">Nova versão</span></header><main class="wrap">${nav}${body}</main><footer>BarberAgenda • Seu negócio, sua agenda</footer>`};
const mobileFix=()=>{if(document.getElementById('ba-mobile-fix'))return;const st=document.createElement('style');st.id='ba-mobile-fix';st.textContent=`html,body{overflow-x:hidden}#app,.wrap{max-width:100%;box-sizing:border-box}.nav{display:flex!important;flex-wrap:wrap!important;gap:8px!important;width:100%!important;max-width:100%!important;overflow:visible!important;height:auto!important}.nav button{display:inline-flex!important;visibility:visible!important;opacity:1!important;position:static!important;flex:1 1 120px!important;min-width:0!important;justify-content:center!important;white-space:normal!important}.wrap .card,.wrap form,.wrap input,.wrap select{max-width:100%;box-sizing:border-box}@media(max-width:600px){.wrap{padding-left:12px!important;padding-right:12px!important}.nav button{font-size:13px!important;padding:11px 7px!important}.card{overflow-wrap:anywhere}.inline{flex-wrap:wrap!important}}`;document.head.appendChild(st)};mobileFix();
const msg=(s,ok=false)=>{const el=document.getElementById('msg');if(el){el.textContent=s;el.className='alert'+(ok?' ok':'')}};
const error=e=>msg(e?.message||String(e));
async function req(path,{method='GET',body,auth=false,headers={}}={}){if(shop&&shopBlocked&&auth&&!path.includes('/rpc/ba2_assinatura_ativa')&&!path.includes('/rpc/ba2_master_')&&!path.includes('/rpc/ba2_is_master')&&!path.includes('/auth/v1/')&&!path.includes('/ba2_barbearias'))throw Error('Barbearia bloqueada. Entre em contato com o administrador.');if(!C?.supabaseUrl||!C?.publishableKey)throw Error('Configuração Supabase ausente');const h={'apikey':C.publishableKey,...headers};if(body!==undefined)h['Content-Type']='application/json';if(auth){if(!session?.access_token)throw Error('Faça login novamente');h.Authorization='Bearer '+session.access_token}const r=await fetch(C.supabaseUrl+path,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body)});let d;try{d=await r.json()}catch{d=null}if(!r.ok)throw Error(d?.message||d?.error_description||d?.msg||d?.error||`Erro ${r.status}`);return d}
const table=(t,query='',opts={})=>req('/rest/v1/'+t+(query?'?'+query:''),opts);
const saveSession=s=>{session=s;try{s?localStorage.setItem('ba_v2_session',JSON.stringify(s)):localStorage.removeItem('ba_v2_session')}catch{}};
const nav=()=>`<div class="nav">${isMaster?'<button onclick="BA.master()">👑 Painel Master</button>':''}${[['dashboard','Painel'],['services','Serviços'],['staff','Profissionais'],['appointments','Agenda'],['clients','Clientes'],['finance','💰 Financeiro'],['settings','Configurações']].map(([k,v])=>`<button class="${current===k?'active':''}" onclick="BA.go('${k}')">${v}</button>`).join('')}<button onclick="BA.logout()">Sair</button></div>`;
const field=(name,label,type='text',val='',extra='')=>`<label>${label}</label><input name="${name}" type="${type}" value="${esc(val)}" ${extra}>`;
function home(){setVisual(null);current='home';shell(`<section class="hero"><span class="pill">Gestão inteligente de barbearias</span><h1>Sua barbearia organizada, <span class="gold">seu tempo valorizado.</span></h1><p class="muted">Agendamentos, profissionais, fidelidade e controle de atendimentos em um só lugar.</p></section><div class="card"><h2>Bem-vindo</h2><p class="muted">Entre ou cadastre sua barbearia para começar.</p><button class="btn" onclick="BA.login()">Entrar</button><button class="btn secondary" onclick="BA.signup()">Criar conta</button></div>`)}
function login(){shell(`<h1>Entrar</h1><form id="form" class="card">${field('email','E-mail','email','','required autocomplete="email"')}${field('password','Senha','password','','required')}<button class="btn">Entrar</button><div id="msg"></div></form><button class="link" onclick="BA.signup()">Criar conta</button>`);document.getElementById('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target),d=await req('/auth/v1/token?grant_type=password',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});saveSession(d);await loadShop()}catch(ex){error(ex)}finally{b.disabled=false}}}
function signup(){shell(`<h1>Criar conta</h1><p class="muted">Comece pelo acesso do responsável.</p><form id="form" class="card">${field('email','E-mail','email','','required')}${field('password','Senha (mínimo 8 caracteres)','password','','required minlength="8"')}<button class="btn">Cadastrar</button><div id="msg"></div></form><button class="link" onclick="BA.login()">Já tenho conta</button>`);document.getElementById('form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),d=await req('/auth/v1/signup',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});if(d?.access_token){saveSession(d);await loadShop()}else msg('Cadastro enviado. Confirme seu e-mail se a confirmação estiver habilitada no Supabase.',true)}catch(ex){error(ex)}}}
async function loadShop(){try{const u=await req('/auth/v1/user',{auth:true});isMaster=await req('/rest/v1/rpc/ba2_is_master',{method:'POST',body:{},auth:true});if(isMaster)return masterPage();const rows=await table('ba2_barbearias','select=*&owner_id=eq.'+encodeURIComponent(u.id)+'&limit=1',{auth:true});shop=rows[0]||null;if(!shop){const pr=await req('/rest/v1/rpc/ba2_meu_perfil_profissional',{method:'POST',body:{},auth:true}).catch(()=>[]);professional=Array.isArray(pr)?pr[0]:pr;if(professional?.id)return professionalPage();return chooseAccount();}if(!await subscriptionCheck())return;await loadVisual(shop.id);await refresh();go('dashboard')}catch(ex){saveSession(null);shell(`<h2>Não foi possível abrir a conta</h2><div class="alert">${esc(ex.message)}</div><button class="btn" onclick="BA.login()">Voltar ao login</button>`)}}
async function subscriptionCheck(){
 if(!shop)return true;
 try{
  let active=await req('/rest/v1/rpc/ba2_assinatura_ativa',{method:'POST',body:{p_barbearia:shop.id},auth:true});
  // Master também está sujeito à suspensão de sua própria barbearia.
  if(isMaster){const shops=await req('/rest/v1/rpc/ba2_master_listar',{method:'POST',body:{},auth:true});const item=shops.find(x=>String(x.id)===String(shop.id));if(!item||item.suspensa===true||['SUSPENSA','VENCIDA','TESTE VENCIDO'].includes(item.situacao))active=false;}
  if(active===true){shopBlocked=false;lastShopCheck=Date.now();return true;}
  shopBlocked=true;lastShopCheck=Date.now();current='blocked';shell(`<h1>Assinatura indisponível</h1><div class="card"><h2>Barbearia temporariamente bloqueada</h2><p>Seu teste ou assinatura venceu, ou o acesso foi suspenso. Entre em contato com o administrador para regularizar.</p>${isMaster?'<button class="btn secondary" onclick="BA.master()">👑 Painel Master</button>':''}<button class="btn secondary" onclick="BA.retryShop()">Verificar novamente</button><button class="btn secondary" onclick="BA.logout()">Sair</button></div>`);
  return false;
 }catch(ex){shopBlocked=true;current='blocked';shell(`<h1>Não foi possível verificar a assinatura</h1><div class="alert">${esc(ex.message)}</div><button class="btn" onclick="BA.retryShop()">Tentar novamente</button><button class="btn secondary" onclick="BA.logout()">Sair</button>`);return false}
}
function chooseAccount(){shell(`<h1>Escolha seu acesso</h1><div class="card"><h2>💈 Dono de barbearia</h2><button class="btn" onclick="BA.setupShop()">Cadastrar minha barbearia</button></div><div class="card"><h2>✂️ Sou profissional</h2><p class="muted">Digite o código de convite fornecido pelo dono da barbearia.</p><form id="joinPro">${field('codigo','Código de convite','text','','required')}<button class="btn">Vincular meu acesso</button><div id="msg"></div></form></div>`);document.getElementById('joinPro').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);await req('/rest/v1/rpc/ba2_vincular_profissional',{method:'POST',body:{p_codigo:String(f.get('codigo')).trim()},auth:true});await loadShop()}catch(ex){error(ex)}}}
function setupShop(){shell(`<h1>Cadastre sua barbearia</h1><p class="muted">Seu teste grátis começa quando criar a barbearia.</p><form id="form" class="card">${field('nome','Nome da barbearia','text','','required')}${field('responsavel','Nome do responsável','text','','required')}${field('whatsapp','WhatsApp com DDD','tel','','required')}<button class="btn">Criar barbearia</button><div id="msg"></div></form>`);document.getElementById('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target),u=await req('/auth/v1/user',{auth:true}),nome=f.get('nome');const payload={owner_id:u.id,nome,responsavel:f.get('responsavel'),whatsapp:f.get('whatsapp'),slug:slug(nome)+'-'+u.id.slice(0,6)};const r=await table('ba2_barbearias','select=*',{method:'POST',body:payload,auth:true,headers:{Prefer:'return=representation'}});shop=r[0];if(!await subscriptionCheck())return;await loadVisual(shop.id);await refresh();go('dashboard')}catch(ex){error(ex)}finally{b.disabled=false}}}
async function refresh(){if(!shop)return;const q='shop_id=eq.'+shop.id+'&select=*';[services,staff,clients,appointments]=await Promise.all(['ba2_servicos','ba2_profissionais','ba2_clientes','ba2_agendamentos'].map(t=>table(t,q,{auth:true})));staff=staff.filter(p=>p.acesso_ativo!==false);capabilities=await table('ba2_staff_services',q,{auth:true})}
const link=()=>{const u=new URL(window.location.href);u.search='';u.hash='';u.searchParams.set('barbearia',shop.slug);return u.href};
async function go(page){if(shop){if(shopBlocked){await subscriptionCheck();return}if(!await subscriptionCheck())return}current=page;if(!shop)return home();if(page==='finance')return financePage();if(['services','staff','appointments','clients','settings'].includes(page))return advancedPage(page);if(page==='dashboard'){
 let notice='';
 try{
   const info=await req('/rest/v1/rpc/ba2_minha_assinatura',{method:'POST',body:{},auth:true});
   const due=info?.vencimento_efetivo;
   if(due){
     const days=Math.ceil((new Date(due).getTime()-Date.now())/86400000);
     const status=String(info.situacao||'');
     if(status==='SUSPENSA'||days<0)notice=`<div class="card" style="border:1px solid #d9534f"><h2>🔴 Assinatura indisponível</h2><p>Entre em contato com a administração para regularizar.</p></div>`;
     else if(days<=7)notice=`<div class="card" style="border:1px solid #e5b23c"><h2>🟡 Aviso de vencimento</h2><p>${days===0?'Seu acesso vence hoje.':days===1?'Seu acesso vence amanhã.':`Faltam ${days} dias para o vencimento.`}</p><p>Renove para continuar recebendo agendamentos.</p></div>`;
     else notice=`<div class="card"><h2>🟢 Acesso em dia</h2><p>${status==='TESTE GRÁTIS'?'Teste grátis':'Assinatura'} válido até ${esc(new Date(due).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}))}.</p></div>`;
   }
 }catch(ex){console.warn('Aviso de assinatura indisponível:',ex.message)}
 const until=new Date(shop.trial_ends_at),expired=until.getTime()<Date.now();shell(`${notice}<h1>Olá, ${esc(shop.nome)} ✂</h1><p class="muted">Gerencie sua barbearia em um só lugar.</p><div class="grid"><div class="card"><div class="muted">Profissionais</div><div class="stat">${staff.length}</div></div><div class="card"><div class="muted">Serviços</div><div class="stat">${services.length}</div></div><div class="card"><div class="muted">Agendamentos</div><div class="stat">${appointments.length}</div></div><div class="card"><div class="muted">Clientes</div><div class="stat">${clients.length}</div></div></div><div class="card"><h2>${expired?'Teste encerrado':'Teste grátis ativo'}</h2><p>Até ${until.toLocaleDateString('pt-BR')}</p><p class="hint">O controle de assinatura e cobrança deverá ser ativado antes da venda comercial.</p></div><div class="card"><h2>Seu link público</h2><p><a href="${esc(link())}">${esc(link())}</a></p><button class="btn" onclick="BA.copyLink()">Copiar link</button><p class="hint">Para clientes externos, publique os arquivos em hospedagem HTTPS antes de divulgar.</p></div>`,nav());return}
if(page==='services'||page==='staff'){const isS=page==='services',arr=isS?services:staff;const name=isS?'Serviços':'Profissionais';shell(`<h1>${name}</h1><form class="card" id="form"><h2>Adicionar ${isS?'serviço':'profissional'}</h2>${field('nome','Nome','text','','required')}${isS?field('preco','Preço em reais','number','','required min="0" step="0.01"')+field('duracao','Duração em minutos','number','30','required min="5" max="600"'):field('whatsapp','WhatsApp (opcional)','tel')}<button class="btn">Salvar</button><div id="msg"></div></form><div class="card"><h2>Cadastrados (${arr.length})</h2>${arr.length?arr.map(x=>`<div class="item row"><div><strong>${esc(x.nome)}</strong><br><small>${isS?money(x.preco)+' • '+x.duracao+' min':esc(x.whatsapp||'Sem WhatsApp')}</small></div>${!isS?`<button class="link" onclick="BA.capability('${x.id}')">Serviços que faz</button>`:''}<button class="link" onclick="BA.remove('${page}','${x.id}')">Excluir</button></div>`).join(''):'<p class="muted">Nenhum cadastro ainda.</p>'}</div>`,nav());document.getElementById('form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),body={shop_id:shop.id,nome:f.get('nome')};if(isS){body.preco=Number(f.get('preco'));body.duracao=Number(f.get('duracao'))}else body.whatsapp=f.get('whatsapp');await table(isS?'ba2_servicos':'ba2_profissionais','',{method:'POST',body,auth:true});await refresh();go(page)}catch(ex){error(ex)}};return}
if(page==='appointments'){shell(`<h1>Agenda</h1><p class="muted">Agendamentos realizados pelo link público.</p><div class="card">${appointments.length?appointments.slice().sort((a,b)=>a.inicio.localeCompare(b.inicio)).map(a=>`<div class="item"><strong>${new Date(a.inicio).toLocaleString('pt-BR')}</strong> • ${esc(a.cliente_nome)}<br><small>${esc(services.find(x=>x.id===a.servico_id)?.nome||'Serviço')} • ${esc(staff.find(x=>x.id===a.profissional_id)?.nome||'Profissional')} • ${esc(a.status)}</small><div class="inline">${a.status==='marcado'?`<button class="link" onclick="BA.status('${a.id}','concluido')">Concluir</button><button class="link" onclick="BA.status('${a.id}','cancelado')">Cancelar</button>`:''}</div></div>`).join(''):'<p class="muted">Nenhum agendamento.</p>'}</div>`,nav());return}
if(page==='clients'){shell(`<h1>Clientes e fidelidade</h1><p class="muted">1 ponto por atendimento concluído, conforme configuração inicial.</p><div class="card">${clients.length?clients.map(c=>`<div class="item row"><div><strong>${esc(c.nome)}</strong><br><small>${esc(c.whatsapp)} • ${c.pontos||0} pontos</small></div></div>`).join(''):'<p class="muted">Os clientes aparecerão após o primeiro agendamento.</p>'}</div>`,nav());return}
if(page==='settings'){shell(`<h1>Configurações</h1><div class="card"><p><strong>Barbearia:</strong> ${esc(shop.nome)}</p><p><strong>Identificador:</strong> ${esc(shop.slug)}</p><p><strong>Link:</strong> <a href="${esc(link())}">${esc(link())}</a></p><p class="hint">Horários padrão: 09:00 às 18:00, de segunda a sábado. A configuração avançada de expediente será adicionada em pacote posterior.</p></div>`,nav())}}
async function remove(page,id){if(!confirm('Excluir este cadastro?'))return;try{if(page==='staff')await req('/rest/v1/rpc/ba2_excluir_profissional',{method:'POST',body:{p_profissional:id},auth:true});else await table('ba2_servicos','id=eq.'+id,{method:'DELETE',auth:true});await refresh();go(page)}catch(ex){alert(ex.message)}}
async function status(id,s){try{await table('ba2_agendamentos','id=eq.'+id,{method:'PATCH',body:{status:s},auth:true});await refresh();go('appointments')}catch(ex){alert(ex.message)}}
function copyLink(){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(link()).then(()=>alert('Link copiado!')).catch(()=>prompt('Copie o link:',link()))}else prompt('Copie o link:',link())}
function capability(id){const p=staff.find(x=>x.id===id);if(!p)return;const existing=capabilities.filter(x=>x.profissional_id===id).map(x=>x.servico_id);shell(`<h1>Serviços de ${esc(p.nome)}</h1><p class="muted">Marque os serviços que este profissional realiza. Se nenhum for marcado, ele poderá realizar todos (padrão).</p><form id="caps" class="card">${services.map(s=>`<label class="checkrow"><input type="checkbox" name="service" value="${s.id}" ${existing.includes(s.id)?'checked':''}> ${esc(s.nome)}</label>`).join('')}<button class="btn">Salvar especialidades</button><div id="msg"></div></form><button class="link" onclick="BA.go('staff')">Voltar</button>`,nav());document.getElementById('caps').onsubmit=async e=>{e.preventDefault();const selected=[...e.target.querySelectorAll('input:checked')].map(x=>x.value);try{await table('ba2_staff_services','profissional_id=eq.'+id,{method:'DELETE',auth:true});for(const servico_id of selected)await table('ba2_staff_services','',{method:'POST',auth:true,body:{shop_id:shop.id,profissional_id:id,servico_id}});await refresh();go('staff')}catch(ex){error(ex)}}}
async function publicPage(sl){shell('<h1>Agendamento online</h1><p class="muted">Carregando horários...</p>');try{
 const result=await req('/rest/v1/rpc/ba2_public_shop',{method:'POST',body:{p_slug:sl}});const r=Array.isArray(result)?result[0]:result;if(!r?.id)throw Error('Barbearia não encontrada');shop=r;await loadVisual(r.id);
 const [s,p,caps]=await Promise.all([
 req('/rest/v1/rpc/ba2_public_services',{method:'POST',body:{p_shop_id:r.id}}),
 req('/rest/v1/rpc/ba2_public_staff',{method:'POST',body:{p_shop_id:r.id}}),
 req('/rest/v1/rpc/ba2_public_capabilities',{method:'POST',body:{p_shop_id:r.id}})]);
 services=s;staff=p;capabilities=caps;
 shell(`<h1>✂ ${esc(r.nome)}</h1><p class="muted">Escolha quantos serviços quiser. Se necessário, selecione profissionais diferentes.</p><form id="booking" class="card"><h2>1. Escolha os serviços</h2><div id="choices">${s.map(x=>`<label class="checkrow"><input type="checkbox" name="services" value="${x.id}"> <span>${esc(x.nome)} — ${money(x.preco)} • ${x.duracao} min</span></label>`).join('')}</div><div id="assignments"></div><div id="total"></div><h2>2. Data e horário</h2>${field('dia','Data','date',isoDay(),`required min="${isoDay()}"`)}<div id="slots"></div><div id="bookingSummary" aria-live="polite"></div><h2>3. Seus dados</h2>${field('nome','Seu nome','text','','required minlength="2"')}${field('whatsapp','WhatsApp com DDD','tel','','required minlength="8"')}<button class="btn" type="submit">Confirmar todos os serviços</button><div id="msg"></div></form>`);
 const form=document.getElementById('booking');let currentItems=[];let seq=0;
 const can=(pid,sid)=>{const set=caps.filter(x=>x.profissional_id===pid);return !set.length||set.some(x=>x.servico_id===sid)};
 const getItems=()=>[...document.querySelectorAll('#assignments select')].map(x=>({servico_id:x.dataset.service,profissional_id:x.value}));
 const showSummary=()=>{const target=document.getElementById('bookingSummary');if(!target)return;if(!selectedSlot){target.innerHTML='';return}let minutes=Number(selectedSlot.split(':')[0])*60+Number(selectedSlot.split(':')[1]);const items=getItems();const fmt=m=>String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');const lines=items.map(item=>{const service=s.find(x=>x.id===item.servico_id),person=p.find(x=>x.id===item.profissional_id);if(!service||!person)return '';const begin=fmt(minutes);minutes+=Number(service.duracao);return `<div class="item"><strong>${esc(service.nome)}</strong> — ${esc(person.nome)}<br><small>${begin} às ${fmt(minutes)} • ${money(service.preco)}</small></div>`}).join('');target.innerHTML=`<div class="card"><h2>Resumo antes de confirmar</h2>${lines}<strong>Total: ${money(items.reduce((sum,item)=>sum+Number(s.find(x=>x.id===item.servico_id)?.preco||0),0))}</strong></div>`};
 const update=async()=>{const run=++seq;selectedSlot='';showSummary();const el=document.getElementById('slots'),day=form.elements.dia.value;currentItems=getItems();if(!currentItems.length||currentItems.some(x=>!x.profissional_id)||!day){el.innerHTML='<p class="hint">Escolha os serviços, profissionais e a data.</p>';return}el.innerHTML='<p class="hint">Buscando horários para todos os serviços...</p>';try{const slots=await req('/rest/v1/rpc/ba2_multi_slots',{method:'POST',body:{p_shop_id:r.id,p_items:currentItems,p_day:day}});if(run!==seq)return;const blocks=await req('/rest/v1/rpc/ba2_public_blocks',{method:'POST',body:{p_shop_id:r.id,p_day:day}});if(run!==seq)return;const freeSlots=slots.filter(x=>slotNotBlocked(x.hora,currentItems,blocks,day));el.innerHTML=`<label>Horários de início disponíveis</label><div class="slots">${freeSlots.length?freeSlots.map(x=>`<button type="button" data-time="${esc(x.hora)}">${esc(x.hora)}</button>`).join(''):'Nenhum horário disponível nessa data.'}</div>`;el.querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedSlot=b.dataset.time;el.querySelectorAll('button').forEach(v=>v.classList.remove('selected'));b.classList.add('selected');showSummary()})}catch(ex){if(run===seq)el.innerHTML='<div class="alert">'+esc(ex.message)+'</div>'}};
 const render=()=>{const chosen=[...form.querySelectorAll('input[name="services"]:checked')].map(x=>s.find(v=>v.id===x.value));const old={};document.querySelectorAll('#assignments select').forEach(x=>old[x.dataset.service]=x.value);const same=staff.find(p=>chosen.every(s=>can(p.id,s.id)));const preferred=same?.id||'';
 document.getElementById('assignments').innerHTML=chosen.length?`<h2>Profissionais por serviço</h2>${chosen.map(s=>{const available=staff.filter(p=>can(p.id,s.id));const preferredId=available.some(p=>p.id===old[s.id])?old[s.id]:(available.some(p=>p.id===preferred)?preferred:available[0]?.id||'');return `<label>${esc(s.nome)}</label><select data-service="${s.id}" required><option value="">Escolha</option>${available.map(p=>`<option value="${p.id}" ${p.id===preferredId?'selected':''}>${esc(p.nome)}</option>`).join('')}</select>${available.length?'':'<p class="alert">Nenhum profissional habilitado para este serviço.</p>'}`}).join('')}`:'<p class="hint">Selecione pelo menos um serviço.</p>';
 document.getElementById('total').innerHTML=chosen.length?`<div class="card"><strong>Total: ${money(chosen.reduce((v,x)=>v+Number(x.preco),0))}</strong><p class="hint">Duração total: ${chosen.reduce((v,x)=>v+x.duracao,0)} minutos • Atendimentos em sequência</p></div>`:'';
 document.querySelectorAll('#assignments select').forEach(x=>x.onchange=update);update()};
 form.querySelectorAll('input[name="services"]').forEach(x=>x.onchange=render);form.elements.dia.onchange=update;render();
 form.onsubmit=async e=>{e.preventDefault();if(!selectedSlot){msg('Escolha um horário disponível.');return}const items=getItems(),f=new FormData(form),btn=form.querySelector('button[type="submit"]'),time=selectedSlot;btn.disabled=true;try{const group=await req('/rest/v1/rpc/ba2_multi_book',{method:'POST',body:{p_shop_id:r.id,p_items:items,p_day:f.get('dia'),p_time:time,p_name:f.get('nome'),p_whatsapp:f.get('whatsapp')}});if(!group)throw Error('Não foi possível confirmar');const confirmation=document.getElementById('bookingSummary')?.innerHTML||'';shell(`<div class="card"><h1>Agendamento confirmado! ✅</h1><p>${esc(f.get('nome'))}, seus ${items.length} serviço(s) foram reservados para ${esc(f.get('dia'))}, começando às ${esc(time)}.</p>${confirmation}<p class="muted">Os serviços serão realizados em sequência. Entre em contato com a barbearia se precisar cancelar.</p><button class="btn" onclick="location.reload()">Novo agendamento</button></div>`)}catch(ex){error(ex);await update()}finally{btn.disabled=false}}
 }catch(ex){shell(`<div class="alert">${esc(ex.message)}</div><p class="hint">Confira se o SQL atualizado foi instalado.</p>`)}}


const localDate=t=>new Date(t).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'});
const slotNotBlocked=(time,items,blocks,day)=>{let minute=Number(time.slice(0,2))*60+Number(time.slice(3,5));return items.every(item=>{const start=minute;minute+=Number(services.find(s=>s.id===item.servico_id)?.duracao||0);return !blocks.some(b=>b.profissional_id===item.profissional_id&&new Date(b.inicio).getTime()<new Date(`${day}T00:00:00-03:00`).getTime()+minute*60000&&new Date(b.fim).getTime()>new Date(`${day}T00:00:00-03:00`).getTime()+start*60000)})};
const dateOnly=t=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t));
const xfield=(name,label,type='text',val='',extra='')=>field(name,label,type,val,extra);
async function financePage(){
 current='finance';shell('<h1>💰 Caixa da barbearia</h1><div class="card">Carregando...</div>',nav());
 try{
  const month=isoDay().slice(0,7),rows=await req('/rest/v1/rpc/ba2_caixa_listar',{method:'POST',body:{p_mes:month},auth:true});
  const ent=rows.filter(x=>x.tipo==='entrada').reduce((a,x)=>a+Number(x.valor||0),0),sai=rows.filter(x=>x.tipo==='saida').reduce((a,x)=>a+Number(x.valor||0),0);
  const opts=staff.map(p=>`<option value="${p.id}">${esc(p.nome)}</option>`).join('');
  const groups={};rows.filter(x=>x.tipo==='entrada').forEach(x=>{const n=x.profissional_nome||'Sem profissional informado';groups[n]=(groups[n]||0)+Number(x.valor||0)});
  shell(`<h1>💰 Caixa da barbearia</h1><p class="muted">Valores realmente recebidos e despesas registradas. A confirmação do Pix continua manual.</p><div class="grid"><div class="card"><div class="muted">Entradas</div><div class="stat">${money(ent)}</div></div><div class="card"><div class="muted">Despesas</div><div class="stat">${money(sai)}</div></div><div class="card"><div class="muted">Lucro</div><div class="stat">${money(ent-sai)}</div></div></div><div class="card"><label>Consultar mês</label><input type="month" id="cashMonth" value="${month}"><button class="btn secondary" onclick="BA.cashReload()">Consultar</button></div><div class="card"><h2>💵 Registrar recebimento</h2><form id="cashIn">${field('valor','Valor recebido (R$)','number','','required min="0.01" step="0.01"')}<label>Forma de pagamento</label><select name="forma" required><option value="pix">Pix</option><option value="dinheiro">Dinheiro</option><option value="debito">Cartão de débito</option><option value="credito">Cartão de crédito</option><option value="outro">Outro</option></select><label>Profissional (opcional)</label><select name="profissional"><option value="">Não informar</option>${opts}</select>${field('descricao','Descrição','text','','required maxlength="160"')}<button class="btn">✅ Confirmar recebimento</button><div id="cashInMsg"></div></form></div><div class="card"><h2>🧾 Registrar despesa</h2><form id="cashOut">${field('valor','Valor da despesa (R$)','number','','required min="0.01" step="0.01"')}${field('categoria','Categoria','text','','required maxlength="60"')}${field('descricao','Descrição','text','','required maxlength="160"')}<button class="btn danger">Registrar despesa</button><div id="cashOutMsg"></div></form></div><div class="card"><h2>✂ Entradas por profissional</h2>${Object.keys(groups).length?Object.entries(groups).map(([n,v])=>`<div class="item"><strong>${esc(n)}</strong><p class="hint">${money(v)}</p></div>`).join(''):'<p class="muted">Nenhum recebimento neste mês.</p>'}</div><div class="card"><h2>📋 Movimentações</h2>${rows.length?rows.map(x=>`<div class="item"><strong>${x.tipo==='entrada'?'🟢 Entrada':'🔴 Saída'} • ${money(x.valor)}</strong><p>${esc(x.descricao||'')}</p><p class="hint">${esc(localDate(x.data_movimento))}${x.forma_pagamento?' • '+esc(x.forma_pagamento):''}${x.categoria?' • '+esc(x.categoria):''}${x.profissional_nome?' • '+esc(x.profissional_nome):''}</p><button class="link" onclick="BA.cashDelete('${x.id}')">Excluir lançamento</button></div>`).join(''):'<p class="muted">Nenhuma movimentação.</p>'}</div>`,nav());
  document.getElementById('cashIn').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await req('/rest/v1/rpc/ba2_caixa_registrar_entrada',{method:'POST',body:{p_valor:Number(f.get('valor')),p_forma:String(f.get('forma')),p_descricao:String(f.get('descricao')).trim(),p_profissional:f.get('profissional')||null},auth:true});alert('Recebimento registrado!');await financePage()}catch(ex){document.getElementById('cashInMsg').textContent=ex.message}finally{b.disabled=false}};
  document.getElementById('cashOut').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await req('/rest/v1/rpc/ba2_caixa_registrar_saida',{method:'POST',body:{p_valor:Number(f.get('valor')),p_categoria:String(f.get('categoria')).trim(),p_descricao:String(f.get('descricao')).trim()},auth:true});alert('Despesa registrada!');await financePage()}catch(ex){document.getElementById('cashOutMsg').textContent=ex.message}finally{b.disabled=false}};
 }catch(ex){shell(`<h1>💰 Caixa da barbearia</h1><div class="alert">${esc(ex.message)}</div><p class="hint">Execute primeiro INSTALAR_CAIXA_REAL.sql no Supabase.</p>`,nav())}
}
async function cashReload(){const m=document.getElementById('cashMonth')?.value;if(!m)return;try{const rows=await req('/rest/v1/rpc/ba2_caixa_listar',{method:'POST',body:{p_mes:m},auth:true}),e=rows.filter(x=>x.tipo==='entrada').reduce((a,x)=>a+Number(x.valor||0),0),d=rows.filter(x=>x.tipo==='saida').reduce((a,x)=>a+Number(x.valor||0),0);shell(`<h1>💰 Caixa • ${esc(m)}</h1><div class="grid"><div class="card"><div class="muted">Entradas</div><div class="stat">${money(e)}</div></div><div class="card"><div class="muted">Despesas</div><div class="stat">${money(d)}</div></div><div class="card"><div class="muted">Lucro</div><div class="stat">${money(e-d)}</div></div></div><div class="card">${rows.map(x=>`<div class="item"><strong>${x.tipo==='entrada'?'🟢':'🔴'} ${money(x.valor)}</strong><p>${esc(x.descricao||'')}</p><p class="hint">${esc(localDate(x.data_movimento))}${x.profissional_nome?' • '+esc(x.profissional_nome):''}</p></div>`).join('')||'<p class="muted">Sem movimentações.</p>'}</div><button class="btn secondary" onclick="BA.go('finance')">Voltar</button>`,nav())}catch(e){alert(e.message)}}
async function cashDelete(id){if(!confirm('Excluir este lançamento do caixa?'))return;try{await req('/rest/v1/rpc/ba2_caixa_excluir',{method:'POST',body:{p_id:id},auth:true});await financePage()}catch(e){alert(e.message)}}


function advancedPage(page){
 if(page==='services'||page==='staff'){
 const isService=page==='services',rows=isService?services:staff;
 shell(`<h1>${isService?'Serviços':'Profissionais'}</h1><div class="card"><h2>Novo cadastro</h2><form id="newEntry">${xfield('nome','Nome','text','','required')}${isService?xfield('preco','Preço (R$)','number','','required min="0" step="0.01"')+xfield('duracao','Duração (minutos)','number','30','required min="5" max="600"'):xfield('whatsapp','WhatsApp (opcional)','tel')}<button class="btn">Adicionar</button><div id="msg"></div></form></div><div class="card"><h2>Cadastrados (${rows.length})</h2>${rows.map(x=>`<div class="item"><strong>${esc(x.nome)}</strong><p class="hint">${isService?money(x.preco)+' • '+esc(x.duracao)+' min':esc(x.whatsapp||'Sem WhatsApp')}</p><div class="inline"><button class="btn secondary" onclick="BA.editEntry('${page}','${x.id}')">Editar</button>${isService?'':`<button class="btn secondary" onclick="BA.capability('${x.id}')">Especialidades</button><button class="btn secondary" onclick="BA.proInvite('${x.id}')">🔐 Acesso</button>`}<button class="btn danger" onclick="BA.remove('${page}','${x.id}')">Excluir</button></div></div>`).join('')||'<p class="muted">Nenhum cadastro.</p>'}</div>`,nav());
 document.getElementById('newEntry').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target),body={shop_id:shop.id,nome:String(f.get('nome')).trim()};if(isService){body.preco=Number(f.get('preco'));body.duracao=Number(f.get('duracao'))}else body.whatsapp=String(f.get('whatsapp')||'');await table(isService?'ba2_servicos':'ba2_profissionais','',{method:'POST',body,auth:true});await refresh();go(page)}catch(ex){error(ex)}finally{b.disabled=false}};return;
 }
 if(page==='appointments'){
 shell(`<h1>Agenda</h1><p class="muted">Consulte os atendimentos e altere o status.</p><div class="card"><label>Data</label><input id="agendaDay" type="date" value="${isoDay()}"><label>Profissional</label><select id="agendaStaff"><option value="">Todos</option>${staff.map(p=>`<option value="${p.id}">${esc(p.nome)}</option>`).join('')}</select><label>Status</label><select id="agendaStatus"><option value="">Todos</option><option value="marcado">Marcado</option><option value="concluido">Concluído</option><option value="cancelado">Cancelado</option></select><button class="btn secondary" id="allDays">📅 Ver somente a data selecionada</button><p class="hint" id="agendaMode">📋 Exibindo todos os agendamentos, em ordem de data e horário.</p></div><div class="card"><h2>Agendamento manual</h2><p class="hint">Cadastre um cliente diretamente na agenda. Os horários são verificados pelo Supabase.</p><form id="manualForm"><label>Serviço</label><select id="manualService" required><option value="">Escolha o serviço</option>${services.map(s=>`<option value="${s.id}">${esc(s.nome)} — ${money(s.preco)}</option>`).join('')}</select><label>Profissional</label><select id="manualStaff" required><option value="">Escolha o profissional</option>${staff.map(p=>`<option value="${p.id}">${esc(p.nome)}</option>`).join('')}</select>${field('manualDay','Data','date',isoDay(),`required min="${isoDay()}"`)}<label>Horários disponíveis</label><select id="manualTime" required><option value="">Selecione serviço, profissional e data</option></select>${field('manualName','Nome do cliente','text','','required minlength="2"')}${field('manualPhone','WhatsApp com DDD','tel','','required minlength="8"')}<button class="btn" type="submit">Confirmar agendamento manual</button><div id="manualMsg" aria-live="polite"></div></form></div><div class="card"><h2>Atendimentos <span id="agendaCount"></span></h2><div id="agendaList"></div></div>`,nav());let allDays=true;const render=()=>{const day=document.getElementById('agendaDay').value,pid=document.getElementById('agendaStaff').value,status=document.getElementById('agendaStatus').value;const rows=appointments.filter(a=>(allDays||dateOnly(a.inicio)===day)&&(!pid||a.profissional_id===pid)&&(!status||a.status===status)).sort((a,b)=>a.inicio.localeCompare(b.inicio));document.getElementById('agendaCount').textContent='('+rows.length+')';const labels={marcado:'📅 Marcados',concluido:'✅ Concluídos',cancelado:'❌ Cancelados'};const groups=['marcado','concluido','cancelado'];const entry=a=>`<div class="item"><strong>${esc(localDate(a.inicio))}</strong> — ${esc(a.cliente_nome)}<p class="hint">${esc(services.find(s=>s.id===a.servico_id)?.nome||'Serviço')} • ${esc(staff.find(p=>p.id===a.profissional_id)?.nome||'Profissional')} • ${esc(a.status)}</p>${a.status==='marcado'?`<div class="inline"><button class="btn secondary" onclick="BA.status('${a.id}','concluido')">Concluir</button><button class="btn danger" onclick="BA.status('${a.id}','cancelado')">Cancelar</button></div>`:''}</div>`;document.getElementById('agendaList').innerHTML=rows.length?groups.map(st=>{const list=rows.filter(a=>a.status===st);return list.length?`<h3 style="margin:26px 0 12px">${labels[st]} (${list.length})</h3>${list.map(entry).join('')}`:''}).join('')+rows.filter(a=>!groups.includes(a.status)).map(entry).join(''):'<p class="muted">Nenhum agendamento neste filtro.</p>'};['agendaDay','agendaStaff','agendaStatus'].forEach(id=>document.getElementById(id).onchange=()=>{if(id==='agendaDay'){allDays=false;document.getElementById('allDays').textContent='📋 Ver todos os agendamentos';document.getElementById('agendaMode').textContent='📅 Exibindo somente a data selecionada.'}render()});document.getElementById('allDays').onclick=()=>{allDays=!allDays;document.getElementById('allDays').textContent=allDays?'📅 Ver somente a data selecionada':'📋 Ver todos os agendamentos';document.getElementById('agendaMode').textContent=allDays?'📋 Exibindo todos os agendamentos, em ordem de data e horário.':'📅 Exibindo somente a data selecionada.';render()};
 let manualSeq=0;
 const manualMsg=(message,ok=false)=>{const e=document.getElementById('manualMsg');if(e){e.textContent=message;e.className=message?'alert'+(ok?' ok':''):''}};
 const manualSlots=async()=>{const n=++manualSeq,service=document.getElementById('manualService').value,person=document.getElementById('manualStaff').value,day=document.querySelector('[name=manualDay]').value,select=document.getElementById('manualTime');select.innerHTML='<option value="">Escolha serviço, profissional e data</option>';manualMsg('');if(!service||!person||!day)return;select.innerHTML='<option value="">Consultando horários...</option>';try{const rows=await req('/rest/v1/rpc/ba2_multi_slots',{method:'POST',body:{p_shop_id:shop.id,p_items:[{servico_id:service,profissional_id:person}],p_day:day}});if(n!==manualSeq)return;const blocks=await req('/rest/v1/rpc/ba2_public_blocks',{method:'POST',body:{p_shop_id:shop.id,p_day:day}});if(n!==manualSeq)return;const freeRows=rows.filter(x=>slotNotBlocked(x.hora,[{servico_id:service,profissional_id:person}],blocks,day));select.innerHTML='<option value="">Escolha um horário</option>'+freeRows.map(x=>`<option value="${esc(x.hora)}">${esc(x.hora)}</option>`).join('');if(!freeRows.length)manualMsg('Não há horários disponíveis para este serviço, profissional e data.')}catch(ex){if(n===manualSeq){select.innerHTML='<option value="">Não foi possível consultar</option>';manualMsg(ex.message)}}};
 const filterManualStaff=()=>{const sid=document.getElementById('manualService').value,sel=document.getElementById('manualStaff'),old=sel.value;const eligible=staff.filter(p=>{const assigned=capabilities.filter(c=>c.profissional_id===p.id);return !sid||!assigned.length||assigned.some(c=>c.servico_id===sid)});sel.innerHTML='<option value="">Escolha o profissional</option>'+eligible.map(p=>`<option value="${esc(p.id)}">${esc(p.nome)}</option>`).join('');if(eligible.some(p=>p.id===old))sel.value=old;else if(eligible.length===1)sel.value=eligible[0].id;if(sid&&!eligible.length)manualMsg('Nenhum profissional habilitado para este serviço.');manualSlots()};document.getElementById('manualService').onchange=filterManualStaff;document.getElementById('manualStaff').onchange=manualSlots;document.querySelector('[name=manualDay]').onchange=manualSlots;
 document.getElementById('manualForm').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),service=document.getElementById('manualService').value,person=document.getElementById('manualStaff').value,day=form.elements.manualDay.value,time=document.getElementById('manualTime').value,name=String(form.elements.manualName.value).trim(),phone=String(form.elements.manualPhone.value).trim();if(!service||!person||!time||!name||!phone){manualMsg('Preencha todos os campos e escolha um horário.');return}button.disabled=true;try{const result=await req('/rest/v1/rpc/ba2_multi_book',{method:'POST',body:{p_shop_id:shop.id,p_items:[{servico_id:service,profissional_id:person}],p_day:day,p_time:time,p_name:name,p_whatsapp:phone}});if(!result)throw Error('Agendamento não confirmado.');await refresh();go('appointments');alert('Agendamento manual confirmado!')}catch(ex){manualMsg(ex.message);await manualSlots()}finally{button.disabled=false}};
 render();return;
 }
 if(page==='clients'){return fidelityPage();}
 if(page==='settings'){
 shell(`<h1>Configurações</h1><form class="card" id="shopSettings"><h2>Dados da barbearia</h2>${xfield('nome','Nome','text',shop.nome,'required')}${xfield('responsavel','Responsável','text',shop.responsavel,'required')}${xfield('whatsapp','WhatsApp','tel',shop.whatsapp,'required')}<button class="btn">Salvar alterações</button><div id="msg"></div></form><div class="card"><h2>💠 Meu Pix</h2><p>Configure seus dados Pix ou gere uma cobrança diretamente.</p><div class="inline"><button class="btn secondary" onclick="BA.pix()">⚙️ Configurar Pix</button><button class="btn" onclick="BA.pixChargePage('settings')">📱 Gerar QR Code</button></div></div><div class="card"><h2>🎨 Aparência da barbearia</h2><p>Logo, cores e imagem de fundo para sua barbearia e agendamento público.</p><button class="btn secondary" onclick="BA.visual()">Personalizar aparência</button></div><div class="card"><h2>Link público</h2><p><a href="${esc(link())}">${esc(link())}</a></p><button class="btn secondary" onclick="BA.copyLink()">Copiar link</button><p class="hint">Os horários públicos continuam definidos pelas funções do Supabase. Não altere o expediente somente na tela: a disponibilidade precisa ser validada pelo banco.</p></div><div class="card"><h2>Bloquear horário</h2><p class="hint">Almoço, folga ou compromisso. Os clientes não poderão reservar durante o bloqueio.</p><form id="blockForm"><label>Profissional</label><select name="profissional" required>${staff.map(p=>`<option value="${p.id}">${esc(p.nome)}</option>`).join('')}</select>${field('dia','Data','date',isoDay(),'required')}${field('inicio','Início','time','12:00','required')}${field('fim','Término','time','13:00','required')}${field('motivo','Motivo (opcional)','text','Almoço')}<button class="btn">Bloquear horário</button><div id="blockMsg"></div></form><h3>Bloqueios cadastrados</h3><div id="blockList">Carregando...</div></div><div class="card"><h2>Teste grátis</h2><p>Válido até ${esc(new Date(shop.trial_ends_at).toLocaleDateString('pt-BR'))}</p><p class="hint">Assinaturas e pagamentos ainda exigem integração segura com um provedor de cobrança.</p></div>`,nav());document.getElementById('shopSettings').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{const f=new FormData(e.target),body={nome:String(f.get('nome')).trim(),responsavel:String(f.get('responsavel')).trim(),whatsapp:String(f.get('whatsapp')).trim()};const updated=await table('ba2_barbearias','id=eq.'+shop.id+'&select=*',{method:'PATCH',body,auth:true,headers:{Prefer:'return=representation'}});shop=updated[0]||{...shop,...body};msg('Configurações salvas!',true)}catch(ex){error(ex)}finally{btn.disabled=false}};
  const loadBlocks=async()=>{try{const rows=await table('ba2_bloqueios','shop_id=eq.'+shop.id+'&select=*&order=inicio.asc',{auth:true});const el=document.getElementById('blockList');if(el)el.innerHTML=rows.map(b=>`<div class="item"><strong>${esc(staff.find(p=>p.id===b.profissional_id)?.nome||'Profissional')}</strong> — ${esc(localDate(b.inicio))} até ${esc(new Date(b.fim).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'}))}<p class="hint">${esc(b.motivo)}</p><button class="btn danger" onclick="BA.deleteBlock('${b.id}')">Remover bloqueio</button></div>`).join('')||'<p class="muted">Nenhum horário bloqueado.</p>'}catch(ex){document.getElementById('blockList').textContent='Erro ao consultar bloqueios: '+ex.message}};
  document.getElementById('blockForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),day=f.get('dia'),begin=f.get('inicio'),end=f.get('fim'),out=document.getElementById('blockMsg'),btn=e.target.querySelector('button');if(end<=begin){out.textContent='O término deve ser depois do início.';return}btn.disabled=true;try{await table('ba2_bloqueios','',{method:'POST',auth:true,body:{shop_id:shop.id,profissional_id:f.get('profissional'),inicio:`${day}T${begin}:00-03:00`,fim:`${day}T${end}:00-03:00`,motivo:f.get('motivo')}});out.textContent='Horário bloqueado com sucesso!';await loadBlocks()}catch(ex){out.textContent=ex.message}finally{btn.disabled=false}};
  window.BA.deleteBlock=async id=>{if(!confirm('Remover este bloqueio?'))return;try{await table('ba2_bloqueios','id=eq.'+id,{method:'DELETE',auth:true});await loadBlocks()}catch(ex){alert(ex.message)}};
  loadBlocks();
 }
}
async function fidelityPage(){
 current='clients';shell('<h1>⭐ Fidelidade</h1><div class="card">Carregando pontos...</div>',nav());
 try{
 const d=await req('/rest/v1/rpc/ba2_fidelidade_resumo',{method:'POST',body:{p_shop_id:shop.id},auth:true});
 const need=Number(d.pontos_necessarios||10),reward=String(d.recompensa||'Um serviço de cortesia');
 const rows=Array.isArray(d.clientes)?d.clientes:[];
 shell(`<h1>⭐ Programa de fidelidade</h1><p class="muted">Cada atendimento concluído vale 1 ponto. Atendimentos cancelados não pontuam.</p>
 <div class="card"><h2>🎁 Configurar recompensa</h2><form id="fidelityConfig">${field('pontos','Pontos necessários','number',need,'required min="1" max="1000"')}${field('recompensa','Prêmio oferecido','text',reward,'required minlength="3" maxlength="150"')}<button class="btn">Salvar recompensa</button><div id="msg"></div></form></div>
 <div class="card"><h2>👥 Pontos dos clientes (${rows.length})</h2><label>Buscar cliente</label><input id="fidelitySearch" placeholder="Nome ou WhatsApp"><div id="fidelityList"></div></div>`,nav());
 const render=()=>{const term=(document.getElementById('fidelitySearch')?.value||'').toLowerCase();document.getElementById('fidelityList').innerHTML=rows.filter(c=>(String(c.nome||'')+' '+String(c.whatsapp||'')).toLowerCase().includes(term)).map(c=>{const earned=Number(c.ganhos||0),used=Number(c.resgatados||0),balance=Math.max(0,earned-used);return `<div class="item"><strong>${esc(c.nome)}</strong><p class="hint">${esc(c.whatsapp)} • ${balance} ponto(s) disponíveis • ${earned} ganho(s) • ${used} resgatado(s)</p>${balance>=need?`<button class="btn secondary" onclick="BA.fidelityRedeem('${c.id}')">🎁 Resgatar ${need} pontos</button>`:`<p class="hint">Faltam ${need-balance} pontos para ${esc(reward)}.</p>`}</div>`}).join('')||'<p class="muted">Nenhum cliente encontrado.</p>'};
 document.getElementById('fidelitySearch').oninput=render;render();
 document.getElementById('fidelityConfig').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('button');btn.disabled=true;try{await req('/rest/v1/rpc/ba2_fidelidade_configurar',{method:'POST',body:{p_shop_id:shop.id,p_pontos:Number(f.get('pontos')),p_recompensa:String(f.get('recompensa')).trim()},auth:true});await fidelityPage()}catch(ex){error(ex)}finally{btn.disabled=false}};
 }catch(ex){shell(`<h1>⭐ Fidelidade</h1><div class="alert">${esc(ex.message)}</div><p class="hint">Execute o arquivo INSTALAR_FIDELIDADE.sql no Supabase.</p>`,nav())}
}
async function fidelityRedeem(id){if(!shop||!confirm('Confirmar entrega da recompensa e descontar os pontos deste cliente?'))return;try{await req('/rest/v1/rpc/ba2_fidelidade_resgatar',{method:'POST',body:{p_shop_id:shop.id,p_cliente_id:id},auth:true});alert('Recompensa resgatada com sucesso!');await fidelityPage()}catch(ex){alert(ex.message)}}
function editEntry(page,id){const isService=page==='services',entry=(isService?services:staff).find(x=>x.id===id);if(!entry)return;current=page;shell(`<h1>Editar ${isService?'serviço':'profissional'}</h1><form class="card" id="editForm">${xfield('nome','Nome','text',entry.nome,'required')}${isService?xfield('preco','Preço (R$)','number',entry.preco,'required min="0" step="0.01"')+xfield('duracao','Duração (minutos)','number',entry.duracao,'required min="5" max="600"'):xfield('whatsapp','WhatsApp','tel',entry.whatsapp||'')}<button class="btn">Salvar alterações</button><div id="msg"></div></form><button class="link" onclick="BA.go('${page}')">Voltar</button>`,nav());document.getElementById('editForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{const f=new FormData(e.target),body={nome:String(f.get('nome')).trim()};if(isService){body.preco=Number(f.get('preco'));body.duracao=Number(f.get('duracao'))}else body.whatsapp=String(f.get('whatsapp')||'');await table(isService?'ba2_servicos':'ba2_profissionais','id=eq.'+id,{method:'PATCH',body,auth:true});await refresh();go(page)}catch(ex){error(ex)}finally{btn.disabled=false}}}

async function loadVisual(id){try{const v=await req('/rest/v1/rpc/ba2_visual_obter',{method:'POST',body:{p_barbearia:id},auth:!!session?.access_token});setVisual(v)}catch(e){console.warn('Aparência:',e);setVisual(null)}}
async function uploadVisual(file,id,kind){if(!file)return null;if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use JPG, PNG ou WEBP.');if(file.size>2*1024*1024)throw Error('Imagem deve ter até 2 MB.');const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';const name=id+'/'+kind+'-'+Date.now()+'.'+ext;const res=await fetch(C.supabaseUrl+'/storage/v1/object/ba2-identidade/'+name,{method:'POST',headers:{apikey:C.publishableKey,Authorization:'Bearer '+session.access_token,'Content-Type':file.type,'x-upsert':'false'},body:file});if(!res.ok){const d=await res.json().catch(()=>({}));throw Error(d.message||d.error||'Falha ao enviar imagem')}return C.supabaseUrl+'/storage/v1/object/public/ba2-identidade/'+name}
async function visualPage(id){if(!session?.access_token)return login();const target=id||shop?.id;if(!target)return alert('Barbearia não selecionada.');if(id&&!isMaster)return alert('Acesso negado.');const fromMaster=!!id;try{const data=await req('/rest/v1/rpc/ba2_visual_obter',{method:'POST',body:{p_barbearia:target},auth:true});const v=data||{};const color=validColor(v.cor);const oldLogo=safeMedia(v.logo_url),oldBg=safeMedia(v.fundo_url);shell(`<h1>🎨 Personalizar aparência</h1><p class="muted">As alterações aparecerão no painel e no link público da barbearia.</p><form id="visualForm" class="card"><label>Cor principal</label><input type="color" name="cor" value="${color}" style="width:100%;height:55px"><label>Logo (JPG, PNG ou WEBP, até 2 MB)</label><p class="hint">Recomendado: 500 × 500 pixels.</p><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"><div id="logoInfo" aria-live="polite"></div>${oldLogo?`<p><img src="${esc(oldLogo)}" style="width:100px;max-height:100px;object-fit:contain"></p>`:''}<label class="checkrow"><input type="checkbox" name="removeLogo"> Remover logo</label><label>Imagem de fundo (até 2 MB)</label><p class="hint">Recomendado: 1080 × 1920 pixels. Cabeçalho/banner: 1200 × 400 pixels.</p><input type="file" name="fundo" accept="image/jpeg,image/png,image/webp"><div id="fundoInfo" aria-live="polite"></div>${oldBg?`<p><img src="${esc(oldBg)}" style="max-width:100%;max-height:140px;object-fit:cover"></p>`:''}<label class="checkrow"><input type="checkbox" name="removeBg"> Remover fundo</label><button class="btn" type="submit">Salvar aparência</button><div id="msg"></div></form><button class="btn secondary" onclick="${fromMaster?'BA.master()':'BA.go(\'settings\')'}">Voltar</button>`,fromMaster?masterNav():nav());const visualForm=document.getElementById('visualForm');
const showImageInfo=(input,infoId,kind)=>{const box=document.getElementById(infoId),file=input.files?.[0];box.innerHTML='';if(!file)return;const typeOk=['image/jpeg','image/png','image/webp'].includes(file.type),sizeOk=file.size<=2*1024*1024;const kb=file.size/1024;const sizeLabel=kb>=1024?(kb/1024).toFixed(2)+' MB':kb.toFixed(0)+' KB';const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const width=img.naturalWidth,height=img.naturalHeight;box.innerHTML=`<div class="card" style="margin:12px 0;padding:12px"><strong>🖼️ Prévia da imagem</strong><p class="hint">📐 ${width} × ${height} pixels • 📦 ${sizeLabel}</p><p class="${typeOk&&sizeOk?'hint':'alert'}">${!typeOk?'Formato não permitido. Use JPG, PNG ou WEBP.':!sizeOk?'Arquivo acima de 2 MB. Escolha uma imagem menor.':'✅ Imagem dentro do limite de 2 MB.'}</p><label>Enquadramento da prévia</label><select class="image-fit"><option value="contain">Mostrar imagem inteira</option><option value="cover">Preencher o espaço (pode cortar)</option></select><div style="margin-top:10px;border:1px solid #777;border-radius:10px;overflow:hidden;max-width:100%;height:${kind==='logo'?'180':'230'}px"><img class="image-preview" alt="Prévia da imagem selecionada" style="width:100%;height:100%;object-fit:contain"></div><p class="hint">Este enquadramento serve para conferir a imagem. A logo é exibida inteira e o fundo preenche a tela no aplicativo.</p></div>`;const preview=box.querySelector('.image-preview');preview.src=url;box.querySelector('.image-fit').onchange=e=>preview.style.objectFit=e.target.value;URL.revokeObjectURL(url)};img.onerror=()=>{URL.revokeObjectURL(url);box.innerHTML='<p class="alert">Não foi possível abrir a imagem.</p>'};img.src=url;};
visualForm.elements.logo.addEventListener('change',e=>showImageInfo(e.target,'logoInfo','logo'));
visualForm.elements.fundo.addEventListener('change',e=>showImageInfo(e.target,'fundoInfo','fundo'));
document.getElementById('visualForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{const f=new FormData(e.target);let logo=f.get('removeLogo')?null:oldLogo;let fundo=f.get('removeBg')?null:oldBg;const fl=f.get('logo'),fb=f.get('fundo');if(fl?.size)logo=await uploadVisual(fl,target,'logo');if(fb?.size)fundo=await uploadVisual(fb,target,'fundo');await req('/rest/v1/rpc/ba2_visual_salvar',{method:'POST',body:{p_barbearia:target,p_cor:f.get('cor'),p_logo_url:logo,p_fundo_url:fundo},auth:true});if(!fromMaster)setVisual({cor:f.get('cor'),logo_url:logo,fundo_url:fundo});alert('Aparência salva!');await visualPage(id)}catch(ex){error(ex)}finally{b.disabled=false}}}catch(e){alert('Erro ao carregar personalização: '+e.message)}}

const masterNav=()=>`<div class="nav"><button onclick="BA.master()">👑 Painel Master</button><button onclick="BA.myShop()">✂ Minha barbearia</button><button onclick="BA.logout()">Sair</button></div>`;
async function myShop(){
 if(!session?.access_token)return login();
 try{
  const u=await req('/auth/v1/user',{auth:true});
  const rows=await table('ba2_barbearias','select=*&owner_id=eq.'+encodeURIComponent(u.id)+'&limit=1',{auth:true});
  shop=rows[0]||null;
  if(!shop){if(isMaster){shell('<h1>Minha barbearia</h1><div class="card">Nenhuma barbearia vinculada a este e-mail.</div>',masterNav());return}return setupShop()}
  if(!await subscriptionCheck())return;
  await refresh();go('dashboard');
 }catch(e){shell(`<h1>Minha barbearia</h1><div class="alert">${esc(e.message)}</div>`,masterNav())}
}
let masterShops=[];
async function masterPage(){
 setVisual(null);shopBlocked=false;shop=null;
 if(!isMaster){alert('Acesso exclusivo do administrador Master.');return}
 current='master';shell('<h1>👑 Painel Master</h1><div class="card">Carregando barbearias...</div>',masterNav());
 try{
  const [rows,payments]=await Promise.all([req('/rest/v1/rpc/ba2_master_listar',{method:'POST',body:{},auth:true}),req('/rest/v1/rpc/ba2_master_listar_pagamentos',{method:'POST',body:{},auth:true})]);
  masterShops=rows;
  const monthKey=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'}).format(new Date(d));
  const thisMonth=monthKey(new Date());
  const paidMonth=payments.filter(p=>monthKey(p.data_pagamento)===thisMonth).reduce((sum,p)=>sum+Number(p.valor||0),0);
  const history=payments.map(p=>`<div class="item"><strong>${esc(p.barbearia)}</strong> • ${money(p.valor)}<br><small>${new Date(p.data_pagamento).toLocaleString('pt-BR')} • ${esc(p.forma_pagamento)}${p.observacao?' • '+esc(p.observacao):''}</small></div>`).join('')||'<p class="muted">Nenhum pagamento registrado.</p>';
  const count=rows.length,active=rows.filter(x=>x.situacao==='ATIVA').length,trial=rows.filter(x=>x.situacao==='TESTE GRÁTIS').length,late=rows.filter(x=>['VENCIDA','TESTE VENCIDO'].includes(x.situacao)).length;
  const revenue=rows.filter(x=>x.situacao==='ATIVA').reduce((a,x)=>a+Number(x.valor||0),0);
   const nowMs=Date.now(),dayMs=86400000;
   const endOf=x=>{const value=x.vencimento||x.fim_teste;const ms=value?new Date(value).getTime():NaN;return Number.isFinite(ms)?ms:null};
   const remaining=x=>{const ms=endOf(x);return ms===null?null:Math.ceil((ms-nowMs)/dayMs)};
   const nearing=rows.filter(x=>!x.suspensa&&['ATIVA','TESTE GRÁTIS'].includes(x.situacao)&&remaining(x)!==null&&remaining(x)>=0&&remaining(x)<=7);
   const expired=rows.filter(x=>['VENCIDA','TESTE VENCIDO'].includes(x.situacao));
   const onTime=rows.filter(x=>x.situacao==='ATIVA'&&!x.suspensa&&remaining(x)!==null&&remaining(x)>7);
   const dueText=x=>{const days=remaining(x);return days===null?'Data não informada':days===0?'Vence hoje':days===1?'Vence amanhã':days<0?`Vencida há ${Math.abs(days)} dia(s)`:`Faltam ${days} dias`};
   const dueList=nearing.slice().sort((a,b)=>endOf(a)-endOf(b)).map(x=>`<div class="item"><strong>${esc(x.nome)}</strong><br><small>${esc(x.situacao)} • ${esc(dueText(x))} • ${new Date(endOf(x)).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small></div>`).join('')||'<p class="muted">Nenhuma barbearia vencendo nos próximos 7 dias.</p>';

  shell(`<h1>👑 Painel Master</h1><p class="muted">Gerenciamento de barbearias e assinaturas</p><div class="grid"><div class="card"><div class="muted">Barbearias</div><div class="stat">${count}</div></div><div class="card"><div class="muted">Assinaturas ativas</div><div class="stat">${active}</div></div><div class="card"><div class="muted">Testes grátis</div><div class="stat">${trial}</div></div><div class="card"><div class="muted">Vencidas</div><div class="stat">${late}</div></div></div><div class="grid"><div class="card"><div class="muted">🟢 Assinaturas em dia (+7 dias)</div><div class="stat">${onTime.length}</div></div><div class="card"><div class="muted">🟡 Vencem em até 7 dias</div><div class="stat">${nearing.length}</div></div><div class="card"><div class="muted">🔴 Vencidas</div><div class="stat">${expired.length}</div></div></div><div class="card"><h2>🟡 Próximos vencimentos</h2><p class="hint">Inclui testes grátis e assinaturas pagas. Contagem em dias aproximados.</p>${dueList}</div><div class="card"><h2>💰 Recebido neste mês</h2><strong>${money(paidMonth)}</strong><p class="hint">Somente pagamentos registrados no Painel Master.</p><button class="btn secondary" onclick="BA.masterPayments()">📋 Histórico de pagamentos</button></div><div class="card"><h2>Valor das assinaturas ativas</h2><strong>${money(revenue)}</strong><p class="hint">Soma dos valores cadastrados, não comprovação de pagamentos recebidos.</p></div>${rows.map(x=>`<div class="card"><h2>${esc(x.nome)}</h2><p><strong>Situação:</strong> ${esc(x.situacao)}</p><p><strong>Responsável:</strong> ${esc(x.responsavel)}</p><p><strong>WhatsApp:</strong> ${esc(x.whatsapp)}</p><p><strong>Teste até:</strong> ${x.fim_teste?new Date(x.fim_teste).toLocaleString('pt-BR'):'—'}</p><p><strong>Plano:</strong> ${esc(x.plano||'Não contratado')} • <strong>Valor:</strong> ${money(x.valor)}</p><p><strong>Vencimento:</strong> ${x.vencimento?new Date(x.vencimento).toLocaleString('pt-BR'):'—'}</p><p><strong>Prazo:</strong> ${esc(dueText(x))}</p><div class="inline"><button class="btn secondary" onclick="BA.visual('${x.id}')">🎨 Aparência</button><button class="btn secondary" onclick="BA.masterPix('${x.id}')">👁 Pix</button><button class="btn secondary" onclick="BA.masterRenew('${x.id}')">Renovar</button><button class="btn secondary" onclick="BA.masterPay('${x.id}')">💰 Registrar pagamento</button><button class="btn secondary" onclick="BA.masterPayRenew('${x.id}')">💳 Receber e renovar</button><button class="btn secondary" onclick="BA.masterWhatsApp('${x.id}')">📲 Cobrar pelo WhatsApp</button><button class="btn ${x.suspensa?'secondary':'danger'}" onclick="BA.masterSuspend('${x.id}',${!x.suspensa})">${x.suspensa?'Reativar':'Suspender'}</button></div></div>`).join('')||'<div class="card">Nenhuma barbearia cadastrada.</div>'}`,masterNav());
 }catch(e){shell(`<h1>Painel Master</h1><div class="alert">${esc(e.message)}</div><button class="btn" onclick="BA.master()">Tentar novamente</button>`,masterNav())}
}
function masterWhatsApp(id){
 if(!isMaster)return;
 const x=masterShops.find(r=>String(r.id)===String(id));
 if(!x){alert('Barbearia não encontrada.');return}
 let phone=String(x.whatsapp||'').replace(/\D/g,'');
 if(phone.length===10||phone.length===11)phone='55'+phone;
 if(!/^\d{12,13}$/.test(phone)){alert('WhatsApp inválido. Confira o cadastro da barbearia.');return}
 const end=x.vencimento||x.fim_teste;
 const date=end?new Date(end).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}):'a confirmar';
 const name=String(x.responsavel||'').trim()||'Olá';
 const message=`Olá, ${name}! Aqui é da BarberAgenda. O acesso da barbearia ${x.nome} tem vencimento em ${date}. Gostaria de conversar sobre a renovação?`;
 window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');
}
async function masterPay(id){
 if(!isMaster)return;
 const v=prompt('Valor recebido em reais (exemplo: 49,90)','49,90');if(v===null)return;
 const amount=Number(v.trim().replace(',','.'));if(!Number.isFinite(amount)||amount<=0){alert('Informe um valor maior que zero.');return}
 const method=prompt('Forma de pagamento (Pix, dinheiro, cartão...)','Pix');if(method===null)return;
 const note=prompt('Observação (opcional)','');if(note===null)return;
 if(!confirm(`Confirmar pagamento recebido de ${money(amount)}?\nIsso registra o recebimento, mas NÃO renova a assinatura.`))return;
 try{await req('/rest/v1/rpc/ba2_master_registrar_pagamento',{method:'POST',body:{p_barbearia:id,p_valor:amount,p_forma:method.trim()||'Pix',p_observacao:note.trim()||null},auth:true});alert('Pagamento registrado com sucesso!');await masterPage()}catch(e){alert(e.message)}
}
async function masterPayRenew(id){
 if(!isMaster)return;
 const d=prompt('Quantos dias de assinatura? (1 a 365)','30');if(d===null)return;
 const days=Number(d);if(!Number.isInteger(days)||days<1||days>365){alert('Informe de 1 a 365 dias.');return}
 const v=prompt('Valor REALMENTE recebido em reais (exemplo: 49,90)','49,90');if(v===null)return;
 const amount=Number(v.trim().replace(',','.'));if(!Number.isFinite(amount)||amount<=0){alert('Informe um valor recebido maior que zero.');return}
 const method=prompt('Forma de pagamento (Pix, dinheiro, cartão...)','Pix');if(method===null)return;
 const note=prompt('Observação (opcional)','');if(note===null)return;
 if(!confirm(`CONFIRMAR: pagamento já recebido de ${money(amount)} e renovação por ${days} dias?\n\nIsso registra um pagamento no histórico e libera/estende a assinatura.`))return;
 try{
  await req('/rest/v1/rpc/ba2_master_pagar_e_renovar',{method:'POST',body:{p_barbearia:id,p_dias:days,p_valor:amount,p_forma:method.trim()||'Pix',p_observacao:note.trim()||null},auth:true});
  alert('Pagamento registrado e assinatura renovada com sucesso!');await masterPage();
 }catch(e){alert('Não foi possível registrar e renovar: '+e.message)}
}
async function masterPayments(){
 if(!isMaster)return;
 shell('<h1>💰 Histórico de pagamentos</h1><div class="card">Carregando...</div>',masterNav());
 try{const payments=await req('/rest/v1/rpc/ba2_master_listar_pagamentos',{method:'POST',body:{},auth:true});
 const total=payments.reduce((a,p)=>a+Number(p.valor||0),0);
 shell(`<h1>💰 Histórico de pagamentos</h1><div class="card"><strong>Total registrado: ${money(total)}</strong><p class="hint">Histórico de recebimentos, sem cobrança automática.</p></div><div class="card">${payments.map(p=>`<div class="item"><strong>${esc(p.barbearia)}</strong> — ${money(p.valor)}<br><small>${new Date(p.data_pagamento).toLocaleString('pt-BR')} • ${esc(p.forma_pagamento)}${p.observacao?' • '+esc(p.observacao):''}</small></div>`).join('')||'<p class="muted">Nenhum pagamento registrado.</p>'}</div><button class="btn secondary" onclick="BA.master()">Voltar ao Painel Master</button>`,masterNav());
 }catch(e){shell(`<h1>Histórico de pagamentos</h1><div class="alert">${esc(e.message)}</div>`,masterNav())}
}
async function masterSuspend(id,suspended){if(!isMaster)return;if(!confirm(suspended?'Suspender esta barbearia?':'Reativar esta barbearia?'))return;try{await req('/rest/v1/rpc/ba2_master_suspender',{method:'POST',body:{p_barbearia:id,p_suspensa:suspended},auth:true});await masterPage()}catch(e){alert(e.message)}}
async function masterRenew(id){if(!isMaster)return;const d=prompt('Quantos dias de assinatura? (1 a 365)','30');if(d===null)return;const days=Number(d);if(!Number.isInteger(days)||days<1||days>365){alert('Informe de 1 a 365 dias.');return}const v=prompt('Valor em reais (exemplo: 49,90)','49,90');if(v===null)return;const amount=Number(v.trim().replace(',','.'));if(!Number.isFinite(amount)||amount<0){alert('Valor inválido.');return}if(!confirm(`Confirmar renovação de ${days} dias por ${money(amount)}?`))return;try{await req('/rest/v1/rpc/ba2_master_renovar',{method:'POST',body:{p_barbearia:id,p_dias:days,p_valor:amount},auth:true});await masterPage()}catch(e){alert(e.message)}}

async function proInvite(id){try{const code=await req('/rest/v1/rpc/ba2_gerar_convite_profissional',{method:'POST',body:{p_profissional:id},auth:true});prompt('Código de acesso do profissional. Envie somente para ele:',code)}catch(e){alert(e.message)}}
const crc16=s=>{let crc=0xFFFF;for(let i=0;i<s.length;i++){crc^=s.charCodeAt(i)<<8;for(let j=0;j<8;j++)crc=(crc&0x8000)?((crc<<1)^0x1021)&0xFFFF:(crc<<1)&0xFFFF}return crc.toString(16).toUpperCase().padStart(4,'0')};
const emv=(id,value)=>id+String(value.length).padStart(2,'0')+value;
function pixPayload(key,name,city,amount){const merchant=emv('00','BR.GOV.BCB.PIX')+emv('01',key);let s=emv('00','01')+emv('26',merchant)+emv('52','0000')+emv('53','986');if(Number(amount)>0)s+=emv('54',Number(amount).toFixed(2));s+=emv('58','BR')+emv('59',String(name).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9 ]/g,'').toUpperCase().slice(0,25))+emv('60',String(city).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9 ]/g,'').toUpperCase().slice(0,15))+emv('62',emv('05','***'))+'6304';return s+crc16(s)}
const pixKeyType=k=>{const v=String(k||'').trim(),n=v.replace(/\D/g,'');if(n.length===11)return 'cpf';if(n.length===14)return 'cnpj';if(v.includes('@'))return 'email';if(/^\+?\d{10,13}$/.test(v.replace(/[\s()\-]/g,'')))return 'telefone';return 'aleatoria'};
const normalizePixKey=(type,key)=>{let v=String(key||'').trim();if(type==='cpf'||type==='cnpj')v=v.replace(/\D/g,'');if(type==='telefone'){v=v.replace(/\D/g,'');if(v.length===10||v.length===11)v='+55'+v;else if(v.startsWith('55'))v='+'+v}return v};
const validatePixKey=(type,key)=>{const v=normalizePixKey(type,key);if(type==='cpf'&&!/^\d{11}$/.test(v))return 'CPF deve ter 11 números.';if(type==='cnpj'&&!/^\d{14}$/.test(v))return 'CNPJ deve ter 14 números.';if(type==='telefone'&&!/^\+55\d{10,11}$/.test(v))return 'Telefone deve ter DDD. Ex.: 17981901221.';if(type==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v))return 'Informe um e-mail válido.';if(type==='aleatoria'&&v.length<10)return 'Informe uma chave aleatória válida.';return ''};
async function pixPage(back='settings'){
 try{const rows=await req('/rest/v1/rpc/ba2_pix_meu',{method:'POST',body:{},auth:true}),x=Array.isArray(rows)?rows[0]:rows||{},type=x.tipo_chave||pixKeyType(x.chave_pix);shell(`<h1>💠 Meu Pix</h1><form id="pixForm" class="card"><label>Tipo da chave Pix</label><select name="tipo" required><option value="cpf" ${type==='cpf'?'selected':''}>CPF</option><option value="cnpj" ${type==='cnpj'?'selected':''}>CNPJ</option><option value="telefone" ${type==='telefone'?'selected':''}>Telefone</option><option value="email" ${type==='email'?'selected':''}>E-mail</option><option value="aleatoria" ${type==='aleatoria'?'selected':''}>Chave aleatória</option></select>${field('chave','Digite sua chave Pix','text',x.chave_pix||'','required autocomplete="off"')}${field('nome','Nome do recebedor','text',x.nome_recebedor||'','required maxlength="25"')}${field('cidade','Cidade do recebedor','text',x.cidade_recebedor||'','required maxlength="15"')}<p class="hint">A chave deve pertencer à conta que receberá o pagamento.</p><button class="btn">Salvar meu Pix</button><div id="msg"></div></form>${x.chave_pix?`<div class="card"><h2>Gerar cobrança</h2>${field('valor','Valor (R$)','number','','min="0.01" step="0.01"')}<button class="btn" onclick="BA.pixCharge()">Gerar Pix Copia e Cola</button><div id="pixCharge"></div></div>`:''}<button class="btn secondary" onclick="${professional?'BA.professional()':`BA.go('${back}')`}">Voltar</button>`,professional?proNav():nav());document.getElementById('pixForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),type=String(f.get('tipo')),key=normalizePixKey(type,f.get('chave')),problem=validatePixKey(type,key);if(problem){msg(problem);return}try{await req('/rest/v1/rpc/ba2_pix_salvar',{method:'POST',body:{p_tipo:type,p_chave:key,p_nome:String(f.get('nome')).trim(),p_cidade:String(f.get('cidade')).trim()},auth:true});alert('Pix salvo!');await pixPage(back)}catch(ex){error(ex)}}}catch(e){alert(e.message)}}
async function loadQrLib(){if(window.QRCode)return true;return new Promise((resolve,reject)=>{const old=document.getElementById('ba2-qrcode-lib');if(old){old.addEventListener('load',()=>resolve(true),{once:true});old.addEventListener('error',()=>reject(Error('Não foi possível carregar o gerador de QR Code.')),{once:true});return}const s=document.createElement('script');s.id='ba2-qrcode-lib';s.src='https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js';s.referrerPolicy='no-referrer';s.onload=()=>resolve(true);s.onerror=()=>reject(Error('Não foi possível carregar o gerador de QR Code.'));document.head.appendChild(s)})}
async function copyPix(){const code=document.getElementById('pixCode')?.value||'';if(!code)return;try{await navigator.clipboard.writeText(code);alert('Pix copiado!')}catch{prompt('Copie o Pix:',code)}}
async function pixChargePage(back='settings'){
 try{
  const rows=await req('/rest/v1/rpc/ba2_pix_meu',{method:'POST',body:{},auth:true}),x=Array.isArray(rows)?rows[0]:rows;
  if(!x?.chave_pix){alert('Cadastre sua chave Pix primeiro.');return pixPage(back)}
  shell(`<h1>📱 Gerar cobrança Pix</h1><div class="card"><p class="muted">Recebedor: <strong>${esc(x.nome_recebedor||'')}</strong></p>${field('valor','Valor (R$)','number','','min="0.01" step="0.01" inputmode="decimal"')}<button class="btn" onclick="BA.pixCharge()">Gerar QR Code</button><div id="pixCharge"></div></div><button class="btn secondary" onclick="${back==='professional'?'BA.professional()':"BA.go('settings')"}">Voltar</button>`,back==='professional'?proNav():nav());
 }catch(e){alert(e.message)}
}
async function pixCharge(){try{const rows=await req('/rest/v1/rpc/ba2_pix_meu',{method:'POST',body:{},auth:true}),x=Array.isArray(rows)?rows[0]:rows;if(!x?.chave_pix)throw Error('Cadastre sua chave Pix primeiro.');const amount=Number(document.querySelector('[name=valor]')?.value||0);if(!(amount>0))throw Error('Informe o valor da cobrança.');const code=pixPayload(x.chave_pix,x.nome_recebedor,x.cidade_recebedor,amount),box=document.getElementById('pixCharge');box.innerHTML=`<div class="card" style="margin-top:14px"><h2>QR Code Pix</h2><div id="pixQr" style="background:#fff;padding:14px;border-radius:12px;width:max-content;max-width:100%;margin:12px auto"></div><p style="text-align:center"><strong>${money(amount)}</strong></p><label>Pix Copia e Cola</label><textarea id="pixCode" rows="6" readonly>${esc(code)}</textarea><button class="btn secondary" onclick="BA.copyPix()">📋 Copiar Pix</button><p class="hint">O valor vai diretamente para a chave Pix cadastrada neste perfil. A confirmação do pagamento não é automática.</p></div>`;try{await loadQrLib();const q=document.getElementById('pixQr');q.innerHTML='';new QRCode(q,{text:code,width:220,height:220,correctLevel:QRCode.CorrectLevel.M})}catch(qe){document.getElementById('pixQr').innerHTML='<p style="color:#111">QR Code indisponível. Use o Pix Copia e Cola abaixo.</p>'}}catch(e){alert(e.message)}}
const proNav=()=>`<div class="nav"><button onclick="BA.professional()">✂ Meu painel</button><button onclick="BA.pix('professional')">💠 Meu Pix</button><button onclick="BA.logout()">Sair</button></div>`;
async function professionalPage(){current='professional';shop=null;try{const rows=await req('/rest/v1/rpc/ba2_meu_perfil_profissional',{method:'POST',body:{},auth:true});professional=Array.isArray(rows)?rows[0]:rows;if(!professional?.id)throw Error('Perfil profissional não vinculado.');shell(`<h1>✂ Olá, ${esc(professional.nome)}</h1><div class="card"><h2>${esc(professional.barbearia)}</h2><p class="muted">Seu acesso individual de profissional.</p></div><div class="card"><h2>💠 Pix individual</h2><p>Sua chave pertence somente ao seu perfil. O dono da barbearia não pode alterá-la.</p><div class="inline"><button class="btn secondary" onclick="BA.pix('professional')">⚙️ Configurar Pix</button><button class="btn" onclick="BA.pixChargePage('professional')">📱 Gerar QR Code</button></div></div>`,proNav())}catch(e){shell(`<h1>Painel profissional</h1><div class="alert">${esc(e.message)}</div>`,proNav())}}
async function masterPix(id){if(!isMaster)return;try{const rows=await req('/rest/v1/rpc/ba2_master_pix',{method:'POST',body:{p_barbearia:id},auth:true});shell(`<h1>👁 Chaves Pix</h1><p class="muted">Consulta somente. O Master não pode alterar ou excluir estas chaves.</p><div class="card">${rows.length?rows.map(x=>`<div class="item"><strong>${esc(x.profissional)}</strong> • ${esc(x.perfil)}<p class="hint">Chave: ${esc(x.chave_pix)}<br>Recebedor: ${esc(x.nome_recebedor)} • ${esc(x.cidade_recebedor)}</p></div>`).join(''):'<p class="muted">Nenhuma chave Pix cadastrada.</p>'}</div><button class="btn secondary" onclick="BA.master()">Voltar</button>`,masterNav())}catch(e){alert(e.message)}}

async function start(){try{const params=new URLSearchParams(location.search);if(params.has('barbearia'))return publicPage(params.get('barbearia'));try{session=JSON.parse(localStorage.getItem('ba_v2_session')||'null')}catch{}if(session?.access_token)return loadShop();home()}catch(ex){shell(`<div class="alert">Erro ao iniciar: ${esc(ex.message)}</div>`)}}
setInterval(async()=>{if(!shop||!session?.access_token||current==='master')return;try{const wasBlocked=shopBlocked;if(await subscriptionCheck()&&wasBlocked)await myShop()}catch(e){console.warn(e)}},5000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&shop&&session?.access_token&&current!=='master')subscriptionCheck()});
window.BA={login,signup,setupShop,professional:professionalPage,pix:pixPage,pixChargePage,pixCharge,copyPix,proInvite,masterPix,fidelityRedeem,retryShop:loadShop,myShop,capability,editEntry,master:masterPage,masterRenew,masterSuspend,masterPay,masterPayRenew,masterPayments,masterWhatsApp,visual:visualPage,cashReload,cashDelete,logout(){saveSession(null);shop=null;shopBlocked=false;isMaster=false;home()},go,remove,status,copyLink};start();
})();